// --- Generated type re-exports (source of truth: server/openapi.json) ---
//
// All schemas from the huma OpenAPI spec are re-exported from
// `@/generated/schemas`, which is auto-generated by
// `scripts/generate-schema-exports.mjs`. To refresh after a server change:
//
//   npm run openapi:gen
//
// That runs three steps in order:
//   1. `openapi:dump` — server emits src/generated/openapi.json
//   2. `openapi:types` — openapi-typescript produces src/generated/api.d.ts
//      (nested components.schemas.* shape)
//   3. `openapi:schemas` — the generator flattens the nested schemas into
//      top-level exports in src/generated/schemas.ts
//
// Prefer importing API types by their exact wire name (e.g. `GameResponse`,
// `UserResponse`). The hand-written types / short-name aliases below exist
// only for historical reasons and will be pruned as call sites migrate.
import type { components } from "@/generated/api";
import type {
  UserResponse,
  SystemEventResponse,
  AuthLoginResponse,
  ConsoleResponse,
  PaginatedResponseGameResponse,
  ChallengeResponse,
  SharedSessionResponse,
  NetplaySessionResponse,
  NetplayInviteResponse,
} from "@/generated/schemas";

export * from "@/generated/schemas";

type Schemas = components["schemas"];

// The wire shape (UserResponse) types role as `string` because huma flattens
// the server's UserRole enum to its JSON representation. Every value the server
// ever emits is one of three literals (see server/internal/db/models.go:17),
// so the frontend narrows the field to keep switch-on-role sites
// exhaustiveness-checked. When a new role is added, this union must grow and
// tsc will flag every switch that doesn't handle it.
export type UserRole = "owner" | "admin" | "user";
export type User = Omit<UserResponse, "role"> & { role: UserRole };

export type RateLimitStatus = Schemas["RateLimitResponse"];

// System event audit log (admin-only). Mirrors the SystemEvent model on
// the server. The metadata blob is per-event-type and may include things like
// failedCount, lockedUntil, consecutiveFailures, etc.
export type SecurityEventType =
  | "login_success"
  | "login_failed"
  | "login_locked"
  | "login_blocked"
  | "account_locked"
  | "revoked_token_used"
  | "disabled_account_token"
  | "token_user_missing"
  | "stale_token_version";

export type OperationalEventType =
  | "ra_circuit_breaker_tripped"
  | "scraper_repeated_errors"
  | "rom_file_missing"
  | "api_credentials_invalid"
  | "emulatorjs_load_failed";

export type SystemEventType = SecurityEventType | OperationalEventType;

export type SystemEventTypeLike = SystemEventType | (string & {});

export type SystemEventCategoryCode = "security" | "operational";

// View-model narrowing — server emits categoryCode and eventType as plain
// strings (huma flattens the Go enums) but the frontend wants the narrow
// literal unions so Record<SystemEventType, EventMeta> / exhaustive switches
// keep working. See system-events-page:156 for the cast at the API boundary.
export type SystemEvent = Omit<
  SystemEventResponse,
  "categoryCode" | "eventType"
> & {
  categoryCode: SystemEventCategoryCode;
  eventType: SystemEventTypeLike;
};

// SystemEventsListResponse and SystemEventTypeInfo are re-exported from
