export type SharedSessionStatus = "active" | "paused" | "completed";

// Derives from the generated SharedSessionResponse; status re-narrowed so
// switches can be exhaustiveness-checked. Note: the previous hand-written
// shape declared description / gameConsoleName / lastActivityAt, which the
// server never emits — those consumers have been migrated to consoleName /
// updatedAt and the description references removed.
export type SharedSession = Omit<SharedSessionResponse, "status"> & {
  status: SharedSessionStatus;
};

export type SharedSessionMemberRole = "owner" | "member";

// Narrows role to the literal union. The server never emits isOnline /
// lastPlayedAt; those fields were aspirational and are removed from the
// type. Consumers that checked for them already rendered nothing at
// runtime.
export type SharedSessionMember = Omit<
  Schemas["SharedSessionMemberResponse"],
  "role"
> & {
  role: SharedSessionMemberRole;
};

export type SharedSessionDetail = Omit<
  Schemas["SharedSessionDetailResponse"],
  "status" | "members"
> & {
  status: SharedSessionStatus;
  members: SharedSessionMember[] | null;
};

